import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';

const shown=[], history=[], queue=[], deltas=[];
let detach=0;
const pending=new Map();
const feed=createProgressFeed({initialPacket:'initial', decode: packet => packet === 'first' || packet === 'second' ? new Promise(resolve => pending.set(packet,resolve)) : packet, onDetach:()=>detach++});
const stopTelemetry=collectProgressTelemetry(feed, frame=>deltas.push(frame));
const ws=createTransferWorkspace({transport(){},onCancel(){},record: row=>queue.push(row),showQueued(){},recordProgress: row=>history.push(row),showProgress: row=>shown.push(row)});
const file={id:'f',progressFeed:feed};
ws.select(file);
assert.deepEqual(shown.map(row=>row.frame),['initial']);
assert.deepEqual(history.map(row=>row.frame),['initial']);
assert.deepEqual(deltas,[]);
feed.emit('first'); feed.emit('second');
pending.get('second')('new'); await Promise.resolve();
pending.get('first')('old'); await Promise.resolve();
assert.deepEqual(shown.map(row=>row.frame),['initial','new']);
assert.deepEqual(history.map(row=>row.frame),['initial','new','old']);
assert.deepEqual(deltas,['new','old']);
ws.hide(); assert.equal(detach,1);
ws.select(file); assert.deepEqual(shown.map(row=>row.frame),['initial','new','initial']);
ws.retry(); assert.deepEqual(queue.map(row=>row.kind),['select','select','retry']);
assert.deepEqual(shown.map(row=>row.frame),['initial','new','initial','initial']);
ws.dispose(); stopTelemetry(); assert.equal(detach,4);
console.log('progress verification passed');
EOF"

